protected String formatMessage(final String msgPattern, final Object... args)
    {
        try
        {
            final MessageFormat temp = new MessageFormat(msgPattern);
            return temp.format(args);
        }
        catch (final IllegalFormatException ife)
        {
            return msgPattern;
        }
    }

