@Override
    public <T> byte[] serialize(final T obj)
        throws IOException
    {
        final ByteArrayOutputStream baos = new ByteArrayOutputStream();

        try (ObjectOutputStream oos = new ObjectOutputStream(baos))
        {
            oos.writeUnshared(obj);
        }

        return baos.toByteArray();
    }

@Override
    public <T> T deSerialize(final byte[] data, final ClassLoader loader)
        throws IOException, ClassNotFoundException
    {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStreamClassLoaderAware(bais, loader))
        {
            @SuppressWarnings("unchecked") // Need to cast from Object
            final
            T readObject = (T) ois.readObject();
            return readObject;
        }
    }

public static <K, V> ICacheElementSerialized<K, V> getSerializedCacheElement( final ICacheElement<K, V> element,
                                                                    final IElementSerializer elementSerializer )
        throws IOException
    {
        if ( element == null )
        {
            return null;
        }

        byte[] serializedValue = null;

        // if it has already been serialized, don't do it again.
        if ( element instanceof ICacheElementSerialized )
        {
            serializedValue = ( (ICacheElementSerialized<K, V>) element ).getSerializedValue();
        }
        else
        {
            if ( elementSerializer == null ) {
                // we could just use the default.
                throw new IOException( "Could not serialize object. The ElementSerializer is null." );
            }
            try
            {
                serializedValue = elementSerializer.serialize(element.getVal());

                // update size in bytes
                element.getElementAttributes().setSize(serializedValue.length);
            }
            catch ( final IOException e )
            {
                log.error( "Problem serializing object.", e );
                throw e;
            }
        }

        return new CacheElementSerialized<>(
                element.getCacheName(), element.getKey(), serializedValue, element.getElementAttributes() );
    }

public static <K, V> ICacheElement<K, V> getDeSerializedCacheElement( final ICacheElementSerialized<K, V> serialized,
                                                            final IElementSerializer elementSerializer )
        throws IOException, ClassNotFoundException
    {
        if ( serialized == null )
        {
            return null;
        }

        V deSerializedValue = null;

        if ( elementSerializer == null ) {
            // we could just use the default.
            throw new IOException( "Could not de-serialize object. The ElementSerializer is null." );
        }
        try
        {
            deSerializedValue = elementSerializer.deSerialize( serialized.getSerializedValue(), null );
        }
        catch ( final ClassNotFoundException | IOException e )
        {
            log.error( "Problem de-serializing object.", e );
            throw e;
        }
        final ICacheElement<K, V> deSerialized = new CacheElement<>( serialized.getCacheName(), serialized.getKey(), deSerializedValue );
        deSerialized.setElementAttributes( serialized.getElementAttributes() );

        return deSerialized;
    }

public void setPreSharedKey(String psk)
    {
        this.psk = psk;
    }

public void setAesCipherTransformation(String transformation)
    {
        this.cipherTransformation = transformation;
    }

private byte[] getRandomBytes(int length)
    {
        byte[] bytes = new byte[length];
        secureRandom.nextBytes(bytes);

        return bytes;
    }

private SecretKey createSecretKey(String password, byte[] salt) throws InvalidKeySpecException
    {
        /* Derive the key, given password and salt. */
        PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), salt,
                KEYHASH_ITERATION_COUNT, KEY_LENGTH);
        SecretKey tmp = secretKeyFactory.generateSecret(spec);
        return new SecretKeySpec(tmp.getEncoded(), "AES");
    }

private byte[] encrypt(byte[] source) throws IOException
    {
        try
        {
            byte[] salt = getRandomBytes(SALT_LENGTH);
            byte[] iv = getRandomBytes(IV_LENGTH);

            SecretKey secretKey = createSecretKey(psk, salt);
            Cipher cipher = Cipher.getInstance(cipherTransformation);
            if (cipher.getAlgorithm().startsWith("AES/GCM"))
            {
                cipher.init(Cipher.ENCRYPT_MODE, secretKey, new GCMParameterSpec(TAG_LENGTH, iv));
            }
            else
            {
                cipher.init(Cipher.ENCRYPT_MODE, secretKey);
            }

            byte[] encrypted = cipher.doFinal(source);

            // join initial vector, salt and encrypted data for later decryption
            return ByteBuffer.allocate(IV_LENGTH + SALT_LENGTH + encrypted.length)
                    .put(iv)
                    .put(salt)
                    .put(encrypted)
                    .array();
        }
        catch (NoSuchAlgorithmException | NoSuchPaddingException | BadPaddingException |
                IllegalBlockSizeException | InvalidKeyException | InvalidKeySpecException |
                InvalidAlgorithmParameterException e)
        {
            throw new IOException("Error while encrypting", e);
        }
    }

private byte[] decrypt(byte[] source) throws IOException
    {
        try
        {
            // split data in initial vector, salt and encrypted data
            ByteBuffer wrapped = ByteBuffer.wrap(source);

            byte[] iv = new byte[IV_LENGTH];
            wrapped.get(iv);

            byte[] salt = new byte[SALT_LENGTH];
            wrapped.get(salt);

            byte[] encrypted = new byte[wrapped.remaining()];
            wrapped.get(encrypted);

            SecretKey secretKey = createSecretKey(psk, salt);
            Cipher cipher = Cipher.getInstance(cipherTransformation);

            if (cipher.getAlgorithm().startsWith("AES/GCM"))
            {
                cipher.init(Cipher.DECRYPT_MODE, secretKey, new GCMParameterSpec(TAG_LENGTH, iv));
            }
            else
            {
                cipher.init(Cipher.DECRYPT_MODE, secretKey);
            }

            return cipher.doFinal(encrypted);
        }
        catch (NoSuchAlgorithmException | NoSuchPaddingException | BadPaddingException |
                IllegalBlockSizeException | InvalidKeyException | InvalidKeySpecException |
                InvalidAlgorithmParameterException e)
        {
            throw new IOException("Error while decrypting", e);
        }
    }

@Override
    public <T> byte[] serialize( final T obj )
        throws IOException
    {
        final byte[] unencrypted = serializer.serialize(obj);
        return encrypt(unencrypted);
    }

@Override
    public <T> T deSerialize( final byte[] data, final ClassLoader loader )
        throws IOException, ClassNotFoundException
    {
        if ( data == null )
        {
            return null;
        }

        final byte[] deccrypted = decrypt(data);
        return serializer.deSerialize(deccrypted, loader);
    }

@Override
    public <T> byte[] serialize( final T obj )
        throws IOException
    {
        final byte[] uncompressed = serializer.serialize(obj);
        return CompressionUtil.compressByteArray( uncompressed );
    }

@Override
    public <T> T deSerialize( final byte[] data, final ClassLoader loader )
        throws IOException, ClassNotFoundException
    {
        if ( data == null )
        {
            return null;
        }

        final byte[] decompressedByteArray = CompressionUtil.decompressByteArray( data );
        return serializer.deSerialize(decompressedByteArray, loader);
    }

