@Override
    public void dispose()
    {
        if (disposed.compareAndSet(false, true))
        {
            if ( listener != null )
            {
                listener.dispose();
                listener = null;
            }

            noWaitMap.values().forEach(LateralCacheNoWait::dispose);
            noWaitMap.clear();
        }
    }

@Override
