@Override
	public void dispose()
	{
		managers.values().forEach(RemoteCacheManager::release);
		managers.clear();

        if (monitor != null)
        {
            monitor.notifyShutdown();
            try
            {
                monitor.join(5000);
            }
            catch (final InterruptedException e)
            {
                // swallow
            }
            monitor = null;
        }

		super.dispose();
	}

@Override
