@Override
    public Map<K, ICacheElement<K, V>> getMultiple( final Set<K> keys ) throws IOException
    {
        if ( keys != null && !keys.isEmpty() )
        {
            for (final RemoteCacheNoWait<K, V> nw : noWaits)
