    {
        final HashSet<K> allKeys = new HashSet<>();
        for (final RemoteCacheNoWait<K, V> nw : noWaits)
        {
            final Set<K> keys = nw.getKeySet();
            if(keys != null)
            {
                allKeys.addAll( keys );
            }
        }

        return allKeys;
    }

@Override
