@Override
    public boolean equals( final Object obj )
    {
        if ( obj == this )
        {
            return true;
        }
        if (!(obj instanceof RemoteLocation))
        {
            return false;
        }
        final RemoteLocation l = (RemoteLocation) obj;
        if ( this.host == null )
        {
            return l.host == null && port == l.port;
        }
        return host.equals( l.host ) && port == l.port;
    }

