    {
        final Map<URI, CacheManager> cacheManagers = cacheManagersByLoader.remove(classLoader);
        if (cacheManagers != null)
        {
            for (final CacheManager mgr : cacheManagers.values())
            {
                mgr.close();
            }
            cacheManagers.clear();
        }
    }

