@Override
    public Map<K, V> loadAll(final Iterable<? extends K> keys) throws CacheLoaderException
    {
        final Map<K, V> result = new HashMap<>();
        for (final K k : keys)
        {
            final V v = load(k);
            if (v != null)
            {
                result.put(k, v);
            }
        }
        return result;
    }

